style.css:
@-moz-document domain("youtube.com") {
/* Aplica la imagen de fondo al cuerpo principal de la página */
  body {
    background-image: url(https://imgur.com/a/6XEiwxp) !important; /* ¡Reemplaza esto con tu URL! */
    background-size: cover !important; /* Ajusta la imagen para cubrir todo el fondo */
    background-repeat: no-repeat !important; /* Evita que la imagen se repita */
    background-attachment: fixed !important; /* Mantiene la imagen fija al hacer scroll */
    background-position: center center !important; /* Centra la imagen */
    background-color: #fcc8ff !important; /* Un color de respaldo si la imagen no carga */
  }

  /*
  OPTIONAL: Ajustar la transparencia de los elementos de YouTube para ver mejor el fondo.
  YouTube es un sitio complejo; estos selectores ayudan a que tu imagen se vea.
  */
  #page-manager,
  ytd-app,
  #contents,
  #primary,
  #secondary,
  #masthead {
background: transparent !important;
  }

  /* OPTIONAL: Cambiar el color del texto para que sea legible sobre tu nuevo fondo */
  body,
  html,
  yt-formatted-string,
  ytd-comment-renderer,
  #description,
  #byline,
  #text,
  #comment-content,
  #content,
  h1, h2, h3, h4, h5, h6,
  p, span, div {
    color: #fff !important; /* Cambia el color del texto a blanco para mejorar el contraste */
  }
}
